arguments.command:
source /opt/miniconda3/bin/activate testbed && python -c "
import sys
for finder in sys.meta_path:
    try:
        spec = finder.find_spec('socket')
        print(f'{finder}: {spec}')
    except Exception as e:
        print(f'{finder}: Error - {e}')
" 2>&1

